class GymMember{protected String memberId;protected int monthlyFee;private int sessionsAttended;public GymMember(String id,int fee){if(id==null||id.trim().length()<4||fee<=0)throw new IllegalArgumentException("Invalid member details");memberId=id;monthlyFee=fee;}public void attendSession(){sessionsAttended++;}public int getSessionsAttended(){return sessionsAttended;}public void displayInfo(){System.out.println("Standard Member | Sessions: "+getSessionsAttended());}}
class PremiumMember extends GymMember{protected String trainerName;public PremiumMember(String id,int fee,String t){super(id,fee);trainerName=t;}public void displayInfo(){System.out.println("Premium Member | Trainer: "+trainerName+" | Sessions: "+getSessionsAttended());}}
class EliteMember extends PremiumMember{private String lockerNumber;public EliteMember(String id,int fee,String t,String l){super(id,fee,t);lockerNumber=l;}public void displayInfo(){System.out.println("Elite Member | Trainer: "+trainerName+" | Locker: "+lockerNumber+" | Sessions: "+getSessionsAttended());}}
class GroupClassMember extends GymMember{private String className;public GroupClassMember(String id,int fee,String c){super(id,fee);className=c;}public void displayInfo(){System.out.println("Group Class Member | Class: "+className+" | Sessions: "+getSessionsAttended());}}
public class GymMembershipTiers{static String classifyGeneration(GymMember m){if(m instanceof EliteMember)return "Multilevel descendant (3 generations deep)";if(m instanceof GroupClassMember)return "Hierarchical sibling (independent branch)";if(m instanceof PremiumMember)return "Second generation (Premium Member)";return "Base generation (Gym Member)";}static int getTotalSessionsAttended(GymMember[] a){int n=0;for(GymMember m:a)n+=m.getSessionsAttended();return n;}public static void main(String[] args){GymMember s=new GymMember("MEM1",1000);PremiumMember p=new PremiumMember("MEM2",2000,"Coach Riya");EliteMember e=new EliteMember("MEM3",3000,"Coach Arjun","L12");GroupClassMember g=new GroupClassMember("MEM4",1500,"Zumba");s.displayInfo();p.displayInfo();e.displayInfo();g.displayInfo();System.out.println(classifyGeneration(e));System.out.println(classifyGeneration(g));for(int i=0;i<3;i++)p.attendSession();for(int i=0;i<2;i++)e.attendSession();for(int i=0;i<4;i++)g.attendSession();System.out.println(getTotalSessionsAttended(new GymMember[]{p,e,g}));}}